import fs from "node:fs";
import path from "node:path";

const configPath = process.argv[1];
const config = JSON.parse(fs.readFileSync(configPath, "utf8"));
const grader = config.fixture_grader;
const root = path.dirname(configPath);

function gradeText(text) {
  const issues = [];
  for (const className of grader.classes) {
    const heading = new RegExp("^##\\s+" + className + "\\s*$", "gmi");
    const matches = [...text.matchAll(heading)];
    if (matches.length !== 1) {
      issues.push(className + ": expected one heading, found " + matches.length);
      continue;
    }

    const bodyStart = matches[0].index + matches[0][0].length;
    const remainder = text.slice(bodyStart);
    const nextHeading = remainder.search(/^##\s+/m);
    const body = (nextHeading === -1 ? remainder : remainder.slice(0, nextHeading)).trim();
    const paragraphs = body.split(/\n\s*\n/).map((paragraph) => paragraph.replace(/\s*\n\s*/g, " ").trim());
    const checked = paragraphs.some((paragraph) => /^Checked:\s+\S(?:.*\S)?\s+—\s+\S(?:.*\S)?$/i.test(paragraph));
    const notApplicable = paragraphs.some((paragraph) => /^N\/A\s+—\s+\S(?:.*\S)?$/i.test(paragraph));
    if (!checked && !notApplicable) {
      issues.push(className + ": missing Checked sites + result or reasoned N/A");
    }
  }
  return { pass: issues.length === 0, issues };
}

let mismatches = 0;
let redText = "";
for (const testCase of grader.cases) {
  const text = fs.readFileSync(path.join(root, testCase.file), "utf8");
  if (testCase.expected_pass === false) redText = text;
  const result = gradeText(text);
  const matched = result.pass === testCase.expected_pass;
  if (!matched) mismatches += 1;
  console.log("CASE " + testCase.file + " expected=" + (testCase.expected_pass ? "PASS" : "FAIL") + " actual=" + (result.pass ? "PASS" : "FAIL") + " " + (matched ? "PASS" : "MISMATCH"));
  if (result.issues.length > 0) console.log("  " + result.issues.join("; "));
}

const renamedGreen = grader.classes.map((className, index) => "## " + className + "\n\nChecked: renamed-site-" + (index + 1) + " — renamed-result-" + (index + 1) + ".").join("\n\n");
const invariants = [
  ["renamed-green-nouns", gradeText(renamedGreen).pass, true],
  ["red-plus-incidental-palette", gradeText(redText + "\n\npalette").pass, false]
];
for (const [name, actual, expected] of invariants) {
  const matched = actual === expected;
  if (!matched) mismatches += 1;
  console.log("INVARIANT " + name + " expected=" + (expected ? "PASS" : "FAIL") + " actual=" + (actual ? "PASS" : "FAIL") + " " + (matched ? "PASS" : "MISMATCH"));
}

console.log("GRADER " + (mismatches === 0 ? "PASS" : "FAIL") + " mismatches=" + mismatches);
if (mismatches > 0) process.exitCode = 1;
